  else:assert sha(target.read_bytes())==h,(rel,'changed after review')
  input_hashes[rel]=h
 reports[n]={'report':p.read_text(),'report_sha256':sha(p.read_bytes()),'evidence':e}
for n in ['docs/decisoes/CONTEXTO-P3.md','docs/PROVA-DE-DIFERENCIACAO.md','eval/qualification/vertical/oracles/tokio/probe.json','eval/adapters/experimental-v1/comparator-plan.json']:
 input_hashes[n]=sha((R/n).read_bytes())
