(O/'revisao.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
md=['IMPLEMENTADOR.md','docs/INTEGRACAO-VERTICAL-RUST.md','docs/PLANO-DE-IMPLEMENTACAO.md','docs/ROTEIRO-V1.md','docs/STATUS-IMPLEMENTACAO.md','docs/relatorios/REVISAO-L5-C06-FECHAMENTO.md']
owned=md+[str((O/n).relative_to(R)) for n in ['revisao.json','documentacao.json']]
