pattern=r'^\| (M[01]-[^|]+) \| ([^|]+) \| ([^|]+) \|';n='docs/STATUS-IMPLEMENTACAO.md'
a=re.findall(pattern,current(n),re.M);assert a==re.findall(pattern,txtold(n),re.M) and len(a)==41
counts=dict(collections.Counter(x[2].strip() for x in a));assert counts=={'concluída':9,'em andamento':7,'não iniciada':25}
assert re.findall(r'^\| G[012] \|.*$',current(n),re.M)==re.findall(r'^\| G[012] \|.*$',txtold(n),re.M)
n='docs/PLANO-DE-IMPLEMENTACAO.md';pat=r'^### (M[01]-[^\n]+)\n\n(\*\*Depende de:\*\*[^\n]+)';assert re.findall(pat,current(n),re.M)==re.findall(pat,txtold(n),re.M) and len(re.findall(pat,current(n),re.M))==41
n='docs/ROTEIRO-V1.md';pat=r'### V1-.*?(?=\n### V1-|\n## 5\.)';assert re.findall(pat,current(n),re.S)==re.findall(pat,txtold(n),re.S) and len(re.findall(pat,current(n),re.S))==6
links=0
for n in md:
 for link in re.findall(r'\[[^\]]*\]\(([^)]+)\)',current(n)):
  if re.match(r'(https?://|mailto:|#)',link):continue
  p=((R/n).parent/link.split('#')[0]).resolve();assert p.exists() or p==O/'documentacao.json',(n,link);links+=1
# Only the historical verifier is rerun because the live plan was edited again.
h=subprocess.run(['python3','-B','eval/adapters/historical-v1/verify.py'],cwd=R,text=True,capture_output=True,check=True)
v=json.loads(h.stdout);assert v['verified'] and v['current_plan_sha256']==sha((R/'docs/PLANO-DE-IMPLEMENTACAO.md').read_bytes()) and v['current_plan_binding_claimed'] is False
subprocess.run(['git','diff','--check','--',*owned],cwd=R,check=True)
changed=set(subprocess.check_output(['git','diff','--name-only'],cwd=R,text=True).splitlines())|set(subprocess.check_output(['git','ls-files','--others','--exclude-standard'],cwd=R,text=True).splitlines())
